import typing

import pytest

from elevenlabs.client import AsyncElevenLabs, ElevenLabs
from elevenlabs.music_custom import AsyncMusicClient, MusicClient
from elevenlabs.realtime_tts import RealtimeTextToSpeechClient
from elevenlabs.speech_engine_custom import AsyncSpeechEngineClient, SpeechEngineClient
from elevenlabs.speech_to_text_custom import AsyncSpeechToTextClient, SpeechToTextClient
from elevenlabs.webhooks_custom import AsyncWebhooksClient, WebhooksClient

# The base client's properties are typed as the autogenerated clients, so type checkers
# reject the custom methods (e.g. `client.webhooks.construct_event`) unless the wrapper
# re-declares each property with the custom client type.
SYNC_PROPERTIES = {
    "text_to_speech": RealtimeTextToSpeechClient,
    "webhooks": WebhooksClient,
    "music": MusicClient,
    "speech_to_text": SpeechToTextClient,
    "speech_engine": SpeechEngineClient,
}
ASYNC_PROPERTIES = {
    "webhooks": AsyncWebhooksClient,
    "music": AsyncMusicClient,
    "speech_to_text": AsyncSpeechToTextClient,
    "speech_engine": AsyncSpeechEngineClient,
}


@pytest.mark.parametrize(
    "client_cls, name, expected",
    [(ElevenLabs, name, cls) for name, cls in SYNC_PROPERTIES.items()]
    + [(AsyncElevenLabs, name, cls) for name, cls in ASYNC_PROPERTIES.items()],
)
def test_custom_client_property_is_typed(client_cls: typing.Any, name: str, expected: type) -> None:
    prop = getattr(client_cls, name)
    assert typing.get_type_hints(prop.fget)["return"] is expected
    assert type(getattr(client_cls(api_key="test"), name)) is expected


def test_construct_event_is_accessible() -> None:
    assert callable(ElevenLabs(api_key="test").webhooks.construct_event)
    assert callable(AsyncElevenLabs(api_key="test").webhooks.construct_event)
